// Compares the host functions of the Wan2.1 DiT (the 4 steps outside the S-shaped graph) with a
// fixture of upstream values. Pure-function tests that need neither a GPU nor real weights (the
// real-GPU run is e2e_wan_dit_test.ts).
//
// The fixture is `fixtures/wan-dit/` (generated by tools/export-recipes/wan/dit_host_fixture.py — the
// expected values are the output of upstream's operations, not a copy of the formulas). The grid is
// F'·H'·W' = 21·3·5, a different value on each of the 3 axes — on a square grid, an axis mix-up would
// hide behind matching values. F' = 21 is the latent time axis of 81 frames (ADR 0118 step 8).
//
// - patchify / unpatchify / the RoPE tables: **bit-exact** (Uint32). All of them only move data.
// - `timesteps_proj`: atol (measured in the doc of `TIMESTEPS_PROJ_ATOL` below).

import { readFile, readTextFile } from "@karume/test-support/fs";
import { test } from "vite-plus/test";
import { assert, assertEquals, assertThrows } from "@std/assert";
import { parseSafetensors, type SafetensorsFile } from "@karume/runtime";
import {
  patchifyLatents,
  unpatchifyTokens,
  type WanPatchGeometry,
  wanTokenGrid,
  wanTokenWidth,
} from "../src/wan/dit-tokens.ts";
import { parseWanRopeBase, wanRopeTables, wanRopeWidth } from "../src/wan/dit-rope.ts";
import { timestepsProj } from "../src/wan/dit-timestep.ts";
import { buildSafetensors, f32Bytes, type TensorSpec } from "./helpers/safetensors.ts";

/**
 * The tolerance (absolute) between the TS implementation of `timesteps_proj` and upstream (torch CPU
 * f32).
 *
 * Measured (2026-10-02, all 1,001 timesteps 0..1,000 × 256 = 256,256 elements): 14,701 mismatches
 * (5.7%), **max absolute difference 3.0517e-5** (t = 745, element 140 = frequency 12 on the sin
 * side).
 *
 * The large differences come only from 1 ULP of `exp`: for 2 of the 128 frequencies (indices 12 and
 * 106), torch's `exp` (SLEEF's 1.0 ULP implementation) and `Math.exp` rounded to f32 differ by 1 ULP
 * (for index 12, against the f64 true value 0.42169649837, torch gives 0.42169651389 and TS
 * 0.42169648409 — TS rounds correctly). Once the angle `t·freq` exceeds 300, 1 ULP becomes 3e-5, and
 * that difference shows up directly in sin / cos. Everything else is 1 ULP of sin / cos (around
 * 6e-8). It is larger than Anima's precedent 6e-7 because the timesteps are integers 0..999 and the
 * angles are large (Anima's measurement had 72 rows, and the angles of the diverging frequencies were
 * small).
 *
 * atol 1.5e-4 is about 4.9 times the measured worst case. Implementation errors differ by orders of
 * magnitude more (the fault injection below: a timestep off by 1 and swapped cos / sin halves are of
 * the order of 1e-1..1e0). The fixture's timesteps are the sequence of the reference setting (50
 * steps, shift 3.0) plus 0 / 1 / 745 (the worst over all timesteps).
 */
const TIMESTEPS_PROJ_ATOL = 1.5e-4;

/** The patch of Wan2.1 T2V 1.3B (`(1,2,2)`, 16 latent channels — the fixture's `host.json`). */
const WAN_GEOMETRY: WanPatchGeometry = {
  channels: 16,
  patchFrames: 1,
  patchHeight: 2,
  patchWidth: 2,
};

const FIXTURE_DIR = new URL("./fixtures/wan-dit/", import.meta.url);

type HostMeta = {
  readonly patch_size: readonly [number, number, number];
  readonly latent_shape: readonly [number, number, number, number];
  readonly rope_base_rows: number;
  readonly timesteps: readonly number[];
};

const readBuffer = async (name: string): Promise<ArrayBuffer> => {
  const bytes = await readFile(new URL(name, FIXTURE_DIR));
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer;
};

const meta = JSON.parse(await readTextFile(new URL("host.json", FIXTURE_DIR))) as HostMeta;
const host = parseSafetensors(await readBuffer("host.safetensors"));
const ropeBaseBuffer = await readBuffer("rope_base.safetensors");

const viewOf = (file: SafetensorsFile, key: string) => {
  const view = file.tensors.get(key);
  if (view === undefined) throw new Error(`the fixture has no '${key}'`);
  return view;
};

const floats = (file: SafetensorsFile, key: string): Float32Array<ArrayBuffer> => {
  const view = viewOf(file, key);
  if (view.dtype !== "F32") throw new Error(`fixture '${key}' is ${view.dtype}`);
  return new Float32Array(file.buffer, view.byteOffset, view.byteLength / 4);
};

const shapeOf = (file: SafetensorsFile, key: string): readonly number[] => viewOf(file, key).shape;

/** The index of the first element whose bits differ (-1 when identical). 0 when the lengths differ. */
const firstBitMismatch = (actual: Float32Array, expected: Float32Array): number => {
  if (actual.length !== expected.length) return 0;
  const left = new Uint32Array(actual.buffer, actual.byteOffset, actual.length);
  const right = new Uint32Array(expected.buffer, expected.byteOffset, expected.length);
  return left.findIndex((bits, index) => bits !== right[index]);
};

const maxAbsDiff = (actual: ArrayLike<number>, expected: ArrayLike<number>): number => {
  let worst = 0;
  for (let index = 0; index < expected.length; index += 1) {
    worst = Math.max(worst, Math.abs(actual[index] - expected[index]));
  }
  return worst;
};

test("fixture: upstream's patch and latent shape match the TS assumptions (Wan2.1 T2V 1.3B)", () => {
  assertEquals(meta.patch_size, [
    WAN_GEOMETRY.patchFrames,
    WAN_GEOMETRY.patchHeight,
    WAN_GEOMETRY.patchWidth,
  ]);
  assertEquals(meta.latent_shape[0], WAN_GEOMETRY.channels);
  assertEquals([...shapeOf(host, "patchify.latents")], [...meta.latent_shape]);
});

test("wanTokenGrid: the grid of the latent [C,F,H,W] divided by the patch, and S = F'·H'·W'", () => {
  assertEquals(wanTokenGrid([16, 9, 60, 104], WAN_GEOMETRY), {
    frames: 9,
    rows: 30,
    cols: 52,
    count: 14_040,
  });
  assertEquals(wanTokenGrid([16, 21, 60, 104], WAN_GEOMETRY).count, 32_760);
});

test("wanTokenGrid: a latent not divisible by the patch, a wrong channel count and a wrong rank fail", () => {
  assertThrows(() => wanTokenGrid([16, 3, 15, 16], WAN_GEOMETRY), Error, "is not divisible by");
  assertThrows(() => wanTokenGrid([4, 3, 16, 16], WAN_GEOMETRY), Error, "channel count");
  assertThrows(() => wanTokenGrid([1, 16, 3, 16, 16], WAN_GEOMETRY), Error, "[C,F,H,W]");
});

test("patchifyLatents: bit-exact with the layout of upstream's patch embedding (1-hot conv3d)", () => {
  const tokens = patchifyLatents(floats(host, "patchify.latents"), meta.latent_shape, WAN_GEOMETRY);
  const expected = floats(host, "patchify.tokens");
  assertEquals(
    firstBitMismatch(tokens, expected),
    -1,
    "the patchify layout diverges from upstream",
  );
});

test("unpatchifyTokens: bit-exact with upstream's output (reshape / permute)", () => {
  const latents = unpatchifyTokens(
    floats(host, "unpatchify.tokens"),
    meta.latent_shape,
    WAN_GEOMETRY,
  );
  const expected = floats(host, "unpatchify.latents");
  assertEquals(
    firstBitMismatch(latents, expected),
    -1,
    "the unpatchify layout diverges from upstream",
  );
});

/** A geometry where the 3 axes and C all differ (a shape only a permutation with a cycle length of 3 or more passes). */
const ODD_GEOMETRY: WanPatchGeometry = {
  channels: 2,
  patchFrames: 2,
  patchHeight: 3,
  patchWidth: 4,
};
const ODD_LATENT = [2, 4, 6, 8] as const;

test("patchify / unpatchify: lay out as the index formula (an independent oracle) says", () => {
  const { channels, patchFrames, patchHeight, patchWidth } = ODD_GEOMETRY;
  const [, frames, height, width] = ODD_LATENT;
  const grid = wanTokenGrid(ODD_LATENT, ODD_GEOMETRY);
  const tokenWidth = wanTokenWidth(ODD_GEOMETRY);
  const latents = Float32Array.from({ length: channels * frames * height * width }, (_, i) => i);
  const tokens = patchifyLatents(latents, ODD_LATENT, ODD_GEOMETRY);
  const back = unpatchifyTokens(tokens, ODD_LATENT, ODD_GEOMETRY);
  for (let c = 0; c < channels; c += 1) {
    for (let f = 0; f < frames; f += 1) {
      for (let h = 0; h < height; h += 1) {
        for (let w = 0; w < width; w += 1) {
          const token =
            (Math.floor(f / patchFrames) * grid.rows + Math.floor(h / patchHeight)) * grid.cols +
            Math.floor(w / patchWidth);
          const inner =
            ((f % patchFrames) * patchHeight + (h % patchHeight)) * patchWidth + (w % patchWidth);
          const value = latents[((c * frames + f) * height + h) * width + w];
          const volume = patchFrames * patchHeight * patchWidth;
          // The input side is (c, pt, ph, pw).
          assertEquals(tokens[token * tokenWidth + c * volume + inner], value);
          // The output side is (pt, ph, pw, c) — reading an input-side token in the output layout
          // scatters it to other pixels.
          assertEquals(
            back[((c * frames + f) * height + h) * width + w],
            tokens[token * tokenWidth + inner * channels + c],
          );
        }
      }
    }
  }
});

test("patchify → permute the last dimension from (c,v) to (v,c) → unpatchify is the identity (round trip)", () => {
  const { channels } = ODD_GEOMETRY;
  const volume = wanTokenWidth(ODD_GEOMETRY) / channels;
  const [, frames, height, width] = ODD_LATENT;
  const latents = Float32Array.from(
    { length: channels * frames * height * width },
    (_, i) => Math.sin(i) * 3,
  );
  const tokens = patchifyLatents(latents, ODD_LATENT, ODD_GEOMETRY);
  const transposed = new Float32Array(tokens.length);
  for (let token = 0; token < tokens.length / (channels * volume); token += 1) {
    for (let c = 0; c < channels; c += 1) {
      for (let v = 0; v < volume; v += 1) {
        transposed[token * channels * volume + v * channels + c] =
          tokens[token * channels * volume + c * volume + v];
      }
    }
  }
  const back = unpatchifyTokens(transposed, ODD_LATENT, ODD_GEOMETRY);
  assertEquals(firstBitMismatch(back, latents), -1);
  // The round trip without the permutation is not the identity (confirming the input and output
  // layouts differ).
  assert(firstBitMismatch(unpatchifyTokens(tokens, ODD_LATENT, ODD_GEOMETRY), latents) !== -1);
});

test("unpatchifyTokens: an element-count mismatch fails", () => {
  assertThrows(
    () => unpatchifyTokens(new Float32Array(10), meta.latent_shape, WAN_GEOMETRY),
    Error,
    "element count",
  );
  assertThrows(
    () => patchifyLatents(new Float32Array(10), meta.latent_shape, WAN_GEOMETRY),
    Error,
    "element count",
  );
});

test("wanRopeTables: the permutation of the raw table is bit-exact with upstream's model.rope tables", () => {
  const base = parseWanRopeBase(ropeBaseBuffer);
  assertEquals(base.rows, meta.rope_base_rows);
  assertEquals(base.widths, [22, 21, 21]);
  assertEquals(wanRopeWidth(base), 128);
  const grid = wanTokenGrid(meta.latent_shape, WAN_GEOMETRY);
  // Covers the latent time axis T' = 21 of 81 frames — every t-axis position 0..20 is compared bit by
  // bit with upstream's table.
  assertEquals(grid.frames, 21);
  const tables = wanRopeTables(base, grid);
  assertEquals([...shapeOf(host, "rope.cos")], [1, grid.count, 1, 128]);
  assertEquals(
    firstBitMismatch(tables.cos, floats(host, "rope.cos")),
    -1,
    "the cos table diverges",
  );
  assertEquals(
    firstBitMismatch(tables.sin, floats(host, "rope.sin")),
    -1,
    "the sin table diverges",
  );
});

test("wanRopeTables: a grid with the h and w positions swapped diverges from upstream's table (a non-square grid)", () => {
  const base = parseWanRopeBase(ropeBaseBuffer);
  const grid = wanTokenGrid(meta.latent_shape, WAN_GEOMETRY);
  const swapped = wanRopeTables(base, { ...grid, rows: grid.cols, cols: grid.rows });
  assert(firstBitMismatch(swapped.cos, floats(host, "rope.cos")) !== -1);
});

test("wanRopeTables: a grid past the raw table's row count fails (the ceiling of upstream's position table)", () => {
  const base = parseWanRopeBase(ropeBaseBuffer);
  assertThrows(
    () => wanRopeTables(base, { frames: 1, rows: base.rows + 1, cols: 1, count: base.rows + 1 }),
    Error,
    "ceiling",
  );
});

/** A raw table of the right shape (2 rows per axis, widths 1 / 2 / 3). The failure cases break one point. */
const ropeSpecs = (): TensorSpec[] =>
  (["t", "h", "w"] as const).flatMap((axis, index) =>
    ["cos", "sin"].map((kind) => ({
      name: `${kind}_${axis}`,
      dtype: "F32",
      shape: [2, index + 1],
      data: f32Bytes(Array.from({ length: 2 * (index + 1) }, (_, i) => i)),
    })),
  );

test("parseWanRopeBase: the right shape returns the row count and width per axis", () => {
  const base = parseWanRopeBase(buildSafetensors(ropeSpecs()));
  assertEquals(base.rows, 2);
  assertEquals(base.widths, [1, 2, 3]);
  assertEquals(wanRopeWidth(base), 12);
});

test("parseWanRopeBase: an unexpected key, a missing one, a wrong row count and a dtype other than F32 fail", () => {
  const extra = [...ropeSpecs(), { name: "cos_x", dtype: "F32", shape: [1], data: f32Bytes([0]) }];
  assertThrows(() => parseWanRopeBase(buildSafetensors(extra)), Error, "unexpected");
  assertThrows(
    () => parseWanRopeBase(buildSafetensors(ropeSpecs().filter((s) => s.name !== "sin_h"))),
    Error,
    "has no 'sin_h'",
  );
  const rows = ropeSpecs().map((spec) =>
    spec.name.endsWith("_w")
      ? { ...spec, shape: [1, 6], data: f32Bytes(new Array(6).fill(0)) }
      : spec,
  );
  assertThrows(() => parseWanRopeBase(buildSafetensors(rows)), Error, "row count");
  const dtype = ropeSpecs().map((spec) =>
    spec.name === "cos_t"
      ? { ...spec, dtype: "I32", data: new Uint8Array(new Int32Array([0, 1]).buffer) }
      : spec,
  );
  assertThrows(() => parseWanRopeBase(buildSafetensors(dtype)), Error, "F32");
});

/** The fixture's timestep sequence and upstream's `timesteps_proj` for it (row = timestep). */
const timestepRows = (): { readonly values: Int32Array; readonly proj: Float32Array } => {
  const view = viewOf(host, "timesteps.values");
  if (view.dtype !== "I32") throw new Error(`timesteps.values is ${view.dtype}`);
  return {
    values: new Int32Array(host.buffer, view.byteOffset, view.byteLength / 4),
    proj: floats(host, "timesteps.proj"),
  };
};

test("timestepsProj: matches upstream's timesteps_proj within atol (cos first, sin second)", () => {
  const { values, proj } = timestepRows();
  const width = shapeOf(host, "timesteps.proj")[1];
  assertEquals(width, 256);
  assertEquals([...values], [...meta.timesteps]);
  let worst = 0;
  values.forEach((timestep, row) => {
    const got = timestepsProj(timestep, width);
    worst = Math.max(worst, maxAbsDiff(got, proj.subarray(row * width, (row + 1) * width)));
  });
  assert(
    worst <= TIMESTEPS_PROJ_ATOL,
    `max absolute difference ${worst} exceeds atol ${TIMESTEPS_PROJ_ATOL}`,
  );
});

test("timestepsProj: a timestep off by 1 and swapped cos / sin halves land outside atol (fault injection)", () => {
  const { values, proj } = timestepRows();
  const width = 256;
  const half = width / 2;
  const row = values.indexOf(999);
  const expected = proj.subarray(row * width, (row + 1) * width);
  const shifted = maxAbsDiff(timestepsProj(998, width), expected);
  const correct = timestepsProj(999, width);
  const flipped = Float32Array.from(
    { length: width },
    (_, i) => correct[i < half ? half + i : i - half],
  );
  const swappedHalves = maxAbsDiff(flipped, expected);
  assert(shifted > 1e3 * TIMESTEPS_PROJ_ATOL, `difference when off by 1: ${shifted}`);
  assert(
    swappedHalves > 1e3 * TIMESTEPS_PROJ_ATOL,
    `difference with swapped halves: ${swappedHalves}`,
  );
});

test("timestepsProj: a width that is not a positive even number, and a negative or non-integer timestep, fail", () => {
  assertThrows(() => timestepsProj(10, 255), RangeError, "even number");
  assertThrows(() => timestepsProj(10, 0), RangeError, "even number");
  assertThrows(() => timestepsProj(-1, 256), RangeError, "integer");
  assertThrows(() => timestepsProj(0.5, 256), RangeError, "integer");
});
